<?php require_once __DIR__.'/../includes/layout.php';require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$status=$_POST['estado']??'';if(in_array($status,['en_espera','atendido','cancelado'],true)){db()->prepare('UPDATE turnos_virtuales SET estado=? WHERE id=?')->execute([$status,$id]);flash('success','Turno actualizado.');}go('admin/turnos.php');}
$items=all('SELECT t.id,t.fecha,t.estado,t.creado_en,u.nombre,u.apellido_paterno,u.telefono FROM turnos_virtuales t JOIN pacientes p ON p.id=t.paciente_id JOIN usuarios u ON u.id=p.usuario_id WHERE t.fecha >= DATE_SUB(CURDATE(),INTERVAL 7 DAY) ORDER BY t.fecha DESC,t.id ASC LIMIT 250');header_ui('Gestor de turnos');?><div class="page-intro"><h2>Fila virtual y atención 🎟️</h2><p>Consulta y actualiza el estado de los turnos solicitados por los pacientes.</p></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Turno</th><th>Paciente</th><th>Fecha</th><th>Teléfono</th><th>Estado / Gestión</th></tr></thead><tbody><?php foreach($items as $r):?><tr><td>#<?=str_pad($r['id'],4,'0',STR_PAD_LEFT)?></td><td><?=e($r['nombre'].' '.$r['apellido_paterno'])?></td><td><?=ui_date($r['fecha'])?></td><td><?=e($r['telefono'])?></td><td><form method="post" class="uc-inline"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="estado"><option value="en_espera" <?=$r['estado']==='en_espera'?'selected':''?>>En espera</option><option value="atendido" <?=$r['estado']==='atendido'?'selected':''?>>Atendido</option><option value="cancelado" <?=$r['estado']==='cancelado'?'selected':''?>>Cancelado</option></select><button class="btn btn-sm btn-primary">Guardar</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php footer_ui(); ?>
